package com.example.assets_management.security.rbac.controller; import com.example.assets_management.security.context.CurrentUserService; import com.example.assets_management.security.rbac.service.EffectivePermissionService; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/users/me") @RequiredArgsConstructor public class CurrentPermissionsController { private final CurrentUserService current; private final EffectivePermissionService service; @org.springframework.security.access.prepost.PreAuthorize("isAuthenticated()") @GetMapping("/permissions") public ResponseEntity<Set<String>> permissions(){return ResponseEntity.ok(service.getEffectivePermissions(current.requireUserId()));} }
